/* From Uiverse.io by G4b413l - Tags: loader */
.__UIV_SCOPE__ .jelly-triangle {
 --uib-size: 42px;
 --uib-speed: 1.25s;
 --uib-color: #512727;
 position: relative;
 height: var(--uib-size);
 width: var(--uib-size);
 filter: url('#uib-jelly-triangle-ooze');
}

.__UIV_SCOPE__ .jelly-triangle__dot,
.__UIV_SCOPE__ .jelly-triangle::before,
.__UIV_SCOPE__ .jelly-triangle::after {
 content: '';
 position: absolute;
 width: 33%;
 height: 33%;
 background: var(--uib-color);
 border-radius: 100%;
}

.__UIV_SCOPE__ .jelly-triangle__dot {
 top: 6%;
 left: 30%;
 animation: grow0 var(--uib-speed) ease infinite;
}

.__UIV_SCOPE__ .jelly-triangle::before {
 bottom: 6%;
 right: 0;
 animation: grow0 var(--uib-speed) ease calc(var(--uib-speed) * -0.666)
    infinite;
}

.__UIV_SCOPE__ .jelly-triangle::after {
 bottom: 6%;
 left: 0;
 animation: grow0 var(--uib-speed) ease calc(var(--uib-speed) * -0.333)
    infinite;
}

.__UIV_SCOPE__ .jelly-triangle__traveler {
 position: absolute;
 top: 6%;
 left: 30%;
 width: 33%;
 height: 33%;
 background: var(--uib-color);
 border-radius: 100%;
 animation: triangulate var(--uib-speed) ease infinite;
}

.__UIV_SCOPE__ .jelly-maker {
 width: 0;
 height: 0;
 position: absolute;
}

@keyframes triangulate {
 0%,
  100% {
  transform: none;
 }

 33.333% {
  transform: translate(120%, 175%);
 }

 66.666% {
  transform: translate(-95%, 175%);
 }
}

@keyframes grow0 {
 0%,
  100% {
  transform: scale(1.5);
 }

 20%,
  70% {
  transform: none;
 }
}
